class MessageObjectBuilder extends fb.ObjectBuilder {
  final AnyMessageTypeId? _msgType;
  final dynamic _msg;
  final List<int>? _metadata;

  MessageObjectBuilder({
    AnyMessageTypeId? msgType,
    dynamic msg,
    List<int>? metadata,
  }) : _msgType = msgType,
       _msg = msg,
       _metadata = metadata;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? msgOffset = _msg?.getOrCreateOffset(fbBuilder);
    final int? metadataOffset = _metadata == null
        ? null
        : fbBuilder.writeListUint8(_metadata!);
    fbBuilder.startTable(3);
    fbBuilder.addUint8(0, _msgType?.value);
    fbBuilder.addOffset(1, msgOffset);
    fbBuilder.addOffset(2, metadataOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = wamp_runtime.WampFlatBufferBuilder(
      deduplicateTables: false,
    );
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}

class Heartbeat {
  Heartbeat._(this._bc, this._bcOffset);
  factory Heartbeat(List<int> bytes) {
    final rootRef = wamp_runtime.bufferContext(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<Heartbeat> reader = _HeartbeatReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  int get ping =>
      const wamp_runtime.WampUint64Reader().vTableGet(_bc, _bcOffset, 4, 0);
  int get incoming =>
      const wamp_runtime.WampUint64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  int get outgoing =>
      const wamp_runtime.WampUint64Reader().vTableGet(_bc, _bcOffset, 8, 0);

  @override
  String toString() {
    return 'Heartbeat{ping: ${ping}, incoming: ${incoming}, outgoing: ${outgoing}}';
  }
}

